{
  "contract": "TRYPTO",
  "closure": {
    "site_function": "take_marketing",
    "site_call": ".call",
    "functions": [
      "take_marketing",
      "transfer",
      "transferFrom"
    ],
    "justification": "Includes all public/external functions that can be called during the callback window and affect the exposed storage."
  },
  "protocol": {
    "during_phase": "exposed",
    "allowed_callbacks": [
      "transfer",
      "transferFrom"
    ],
    "nesting_bound": {
      "transfer": 1,
      "transferFrom": 1
    }
  },
  "phases": {
    "function": "take_marketing",
    "pre": {
      "name": "pre",
      "from_marker": "entry",
      "to_marker": "before .call"
    },
    "exposed": {
      "name": "exposed",
      "from_marker": "before .call",
      "to_marker": "after .call"
    },
    "post": {
      "name": "post",
      "from_marker": "after .call",
      "to_marker": "exit"
    },
    "linearization_point": "after .call"
  },
  "ghost_state": [
    {
      "name": "inFlight",
      "sol_type": "uint256",
      "meaning": "Amount of ETH in-flight during the callback window.",
      "backed_by_storage": false
    }
  ],
  "exposure_invariant": {
    "formula": "marketing_balance + growth_balance + inFlight <= _ethBal",
    "stable_formula": "marketing_balance + growth_balance <= _ethBal",
    "kind": "bounded"
  },
  "composition": {
    "target_property": "marketing_balance + growth_balance <= _ethBal",
    "rule": "The exposure invariant ensures that the sum of marketing_balance and growth_balance, plus any in-flight ETH, does not exceed _ethBal during the callback."
  }
}
